// サーバ情報の設定
msg.urlRoot = setting.urlRoot;

// シリアル番号(11桁)
var tmpSerialNo = '0';
if (setting.serial_no !== undefined && setting.serial_no !== null && setting.serial_no !== '') {
    tmpSerialNo = setting.serial_no;
}
var SerialNo = commonLib.LeftAppend(tmpSerialNo, 11, '0');

// 施設コード（6桁）
