var commonLib = global.get('commonLib');
var fs = global.get('fs');
var path = global.get('path');
var array = msg.payload

var maintEcecCmd = env.get('NTSS_MAINT_EXEC_CMD');
//node.log(maintEcecCmd);
var items = maintEcecCmd.split(' ');

var maintShellPath = items[items.length-1];
var maintRoot = path.dirname(maintShellPath) + '/';
var maintShell = path.basename(maintShellPath);
var eyecatchCtlNo = 'ctlno_'

node.log(maintShellPath);
node.log(maintRoot);
node.log(maintShell);

msg.status = '500';

// あれば消す
if (commonLib.isExist(maintShellPath)) {
    // maintenance shellの削除
    fs.unlinkSync(maintShellPath);
node.log('delete file [' + maintShellPath + ']');
}

for(var file of array) {
    file.filename = file.filename.replace(/\\/g, '/');
node.log('-------->zip file =['+ file.filename + ']');
    if (file.filename.slice( -1 ) === '/') {
        // ディレクトリなければ作る
        if (!commonLib.isExist(maintRoot + file.filename)) {
            fs.mkdirSync(maintRoot + file.filename);
        }
node.log('    ---->path = [' + maintRoot + file.filename + ']');      
    } else {
        // ファイル
        if (file.filename.match(eyecatchCtlNo)) {
            const filename = path.basename(file.filename);
            msg.ctlNo = 1 * filename.replace(eyecatchCtlNo, '');
        }

        if (file.filename.match(maintShell)) {
            fs.writeFileSync(maintShellPath, file.payload);
node.log('    ---->creat file = [' + maintShellPath, file.payload + ']');           
        }
        fs.writeFileSync(maintRoot + file.filename, file.payload);
node.log('    ---->creat file = [' + maintRoot + file.filename + ']');   
    }
}


if (fs.existsSync(maintShellPath)) {
    return [msg, null];
} else {
    msg.retMessage = maintShell +'が存在しません';
    return [null, msg];
}


function isExist(path) {
    var fs =global.get('fs');

    try {
        fs.statSync(path);
    } catch (err) {
        if (err.code === 'ENOENT') {
            return false;
        } else {
            throw new Error('Exeption occured at File Exist check ' + isExist.name);
        }
    }
    return true;
}

if (msg.rc.code === 0) {
    // 成功
    msg.status = '200';
    msg.retMessage = msg.payload;
} else {
    // 失敗
    msg.status = '500';
    msg.retMessage = msg.rc.message;
}

return msg;

