// 2023-03-02 bug #7175 連携エッジ内のファイル管理 孫
var commonLib = global.get('commonLib');
var setting = commonLib.getSettings();
var path = global.get('path');

var fileKeepDays = setting.fileKeepDays;
node.log('Maint電文の保留期間:　' + fileKeepDays + '　日');
if (undefined === fileKeepDays || null === fileKeepDays || '' === fileKeepDays) {
    node.log('Maint電文の保留期間不正');
    return;
}

var maintEcecCmd = env.get('NTSS_MAINT_EXEC_CMD');
var items = maintEcecCmd.split(' ');

var maintShellPath = items[items.length - 1];
var keepDirRoot = path.dirname(maintShellPath);
node.log('Maint電文の保管フォルダ:[' + keepDirRoot + ']');
if (undefined === keepDirRoot || null === keepDirRoot || '' === keepDirRoot) {
    node.log('Maint電文の保管フォルダ不正');
    return;
}

msg.fileKeepDays = fileKeepDays;
msg.keepDirRoot = keepDirRoot;
msg.type = msg.payload;
return msg;

// 古いmaintファイルのを削除する
var commonLib = global.get('commonLib');
var fs = global.get('fs');

var fileKeepDays = msg.fileKeepDays;
var keepDirRoot = msg.keepDirRoot;
var deleteType = msg.type;

let dtNow = new Date();
let dtTarget = new Date(new Date().setDate(new Date().getDate() - fileKeepDays));
let dtMonth = ((dtTarget.getMonth() + 1) < 10) ? '0' + (dtTarget.getMonth() + 1) : dtTarget.getMonth() + 1;
let dtDate = (dtTarget.getDate() < 10) ? '0' + dtTarget.getDate() : dtTarget.getDate();
let strDtTarget = dtTarget.getFullYear().toString() + dtMonth + dtDate;

let logMsg = '';
try {
    let dataTypeDirs = fs.readdirSync(keepDirRoot);
    if (0 === dataTypeDirs.length) {
        node.log(keepDirRoot + 'にMaintファイルのがありません。');
        return;
    }

    //タイプづつ
    for (var dataTypeDir of dataTypeDirs) {
        var maintPath = keepDirRoot + '/' + dataTypeDir;
        let maintPathStats = fs.statSync(maintPath);
        if (maintPathStats.isDirectory()) {
            let dataTypeDirComp = dataTypeDir.substr(0, 8);
            if (dataTypeDirComp > strDtTarget) {
                node.log(maintPath + '(日付:' + dataTypeDirComp + ')は削除対象外のため削除しません。');
                continue;
            }
            msg.cmd = makeDeleteDirCmd(maintPath);
            logMsg = maintPath + 'を削除しました。';
            node.log(logMsg);
            msg.logMsg = logMsg;
            node.send(msg);
        } else {
            // mod 2023-03-13 bug #7175 連携エッジ内のファイル管理 孫 start
            //let ctimeYYYY = maintPathStats.ctime.getFullYear().toString();
            //let ctimeMM = ((maintPathStats.ctime.getMonth() + 1) < 10) ? '0' + (maintPathStats.ctime.getMonth() + 1) : maintPathStats.ctime.getMonth() + 1;
            //let ctimeDD = ((maintPathStats.ctime.getDate()) < 10) ? '0' + (maintPathStats.ctime.getDate()) : maintPathStats.ctime.getDate();
            //let ctimeOrg = ctimeYYYY + ctimeMM + ctimeDD;
            let yyyy = maintPathStats.mtime.getFullYear();
            let mm = maintPathStats.mtime.getMonth() + 1;
            let dd = maintPathStats.mtime.getDate()
            let ctimeOrg = yyyy + ("00" + mm).slice(-2) + ("00" + dd).slice(-2);
            // mod 2023-03-13 bug #7175 連携エッジ内のファイル管理 孫 end
            msg.ctime = ctimeOrg;
            if (ctimeOrg > strDtTarget) {
                node.log(maintPath + '(日付:' + ctimeOrg + ')は削除対象外のため削除しません。');
                continue;
            }

            msg.cmd = makeDeleteFileCmd(maintPath);
            logMsg = maintPath + 'を削除しました。';
            node.log(logMsg);
            msg.logMsg = logMsg;
            node.send(msg);
        }
        await sleep(500);
    }
} catch (err) {
    node.log(err);
}

function makeDeleteDirCmd(dir) {
    return 'rm -rf ' + dir;
}

function makeDeleteFileCmd(file) {
    return 'rm ' + file;
}

function sleep(time = 0) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve();
        }, time);
    })
}
return;

if (msg.rc.code === 0) {
    // OK
    msg.message = 'Delete Old File Cmd OK.[' + msg.cmd + ']';
    //node.log(msg.message);

    node.send([msg, null]);
} else {
    // NG
    msg.message = 'Delete Old File Cmd NG.[' + msg.cmd + ']. message=' + msg.rc.message;
    node.log(msg.message);

    node.send([null, msg]);
}
return;

// websocket connect status change
var maintWsStatus = msg.status.event;
// last connect status
var lastMaintWsStatus = global.get('maintWsStatus');
if (!lastMaintWsStatus || maintWsStatus != lastMaintWsStatus) {
    let wsUrl = env.get('NTSS_MAINT_WEBSOCKET_URL');
    if (maintWsStatus == 'connect') {
        global.set('maintWsStatus', maintWsStatus);
        var websocketstatMsg = '[' + wsUrl + '] Connected.';
        node.log(websocketstatMsg);
        // record log file
        msg.websocketstatMsg = websocketstatMsg;
        node.send([null, msg]);

        // need send message
        msg.payload = {};
        msg.payload.status = 'connect';
        node.send([msg, null]);
    } else if (maintWsStatus == 'disconnect') {
        global.set('maintWsStatus', maintWsStatus);
        var websocketstatMsg = wsUrl + ' is on CLOSE state.';
        node.log(websocketstatMsg);
        msg.websocketstatMsg = websocketstatMsg;
        node.send([null, msg]);
    }

}
